<?php
require_once '../config/crud_service.php';require_role('admin');require_once '../includes/crud.php';$error='';$edit=null;$endpoint=!empty($is_assignment_page)?'penugasan.php':'jadwal.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{save_schedule($_POST);flash('success',in_array($_POST['action']??'',['delete','deactivate'],true)?'Penugasan dinonaktifkan; arsip dipertahankan.':'Jadwal dan penugasan berhasil disimpan.');redirect($endpoint);}catch(Throwable $e){$error=operation_error($e);$edit=$_POST;}}
elseif(isset($_GET['edit'])){$q=db()->prepare('SELECT * FROM jadwal WHERE id_jadwal=?');$q->execute([input_id($_GET,'edit')]);$edit=$q->fetch();if(!$edit)not_found();}
$search=input_text($_GET,'q',100,false);$where=[];$args=[];
if($search!==''){$where[]='(g.nama_guru LIKE ? OR k.nama_kelas LIKE ? OR m.nama_mapel LIKE ? OR j.ruang LIKE ?)';$args=array_fill(0,4,'%'.$search.'%');}
foreach(['id_guru','id_kelas','id_mapel','id_tahun_ajaran'] as $key)if(($_GET[$key]??'')!==''){$where[]='j.'.$key.'=?';$args[]=input_id($_GET,$key);}
$status=input_text($_GET,'status',10,false);if(!in_array($status,['','aktif','nonaktif'],true))throw new InputError('Status tidak valid.');if($status!==''){$where[]='j.status=?';$args[]=$status;}
$from=' FROM jadwal j JOIN guru g ON g.id_guru=j.id_guru JOIN kelas k ON k.id_kelas=j.id_kelas JOIN mata_pelajaran m ON m.id_mapel=j.id_mapel LEFT JOIN tahun_ajaran t ON t.id_tahun_ajaran=j.id_tahun_ajaran';$filter=$where?' WHERE '.implode(' AND ',$where):'';
$q=db()->prepare('SELECT COUNT(*)'.$from.$filter);$q->execute($args);$total=(int)$q->fetchColumn();[$page,$pages,$offset]=crud_page_bounds($total);
$q=db()->prepare('SELECT j.*,g.nama_guru,k.nama_kelas,m.nama_mapel,t.tahun_ajaran,t.semester'.$from.$filter." ORDER BY j.id_jadwal DESC LIMIT 20 OFFSET $offset");$q->execute($args);$rows=$q->fetchAll();
$teachers=crud_options('guru','id_guru','nama_guru');$classes=crud_options('kelas','id_kelas','nama_kelas');$subjects=crud_options('mata_pelajaran','id_mapel','nama_mapel');$years=[];foreach(db()->query('SELECT * FROM tahun_ajaran ORDER BY id_tahun_ajaran DESC') as $y)$years[$y['id_tahun_ajaran']]=$y['tahun_ajaran'].' '.$y['semester'];
$page_title=!empty($is_assignment_page)?'Penugasan Guru Mengajar':'Jadwal Pelajaran';$crud_ui=true;require '../includes/header.php';require '../includes/sidebar.php';require '../includes/flash.php';
?><div class="crud-toolbar"><h2><?=e($page_title)?></h2><div class="crud-actions"><a class="btn btn-outline-dark" href="<?=$endpoint?>">Penugasan baru</a><a class="btn btn-outline-dark" href="penugasan.php">Penugasan guru</a></div></div>
<p class="crud-note">Pilih guru, kelas, mata pelajaran dan periode. Bentrok waktu guru, kelas dan ruang ditolak. Penugasan yang memiliki arsip tidak diganti konteksnya; nonaktifkan dan buat penugasan baru. Penugasan lama tanpa periode harus ditinjau sebelum pencatatan baru.</p>
<?php if($error):?><div role="alert" class="alert alert-danger"><?=e($error)?></div><?php endif;?>
<form method="post" class="card p-3 mb-4 crud-grid"><?=csrf_field()?><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><input type="hidden" name="id_jadwal" value="<?=e($edit['id_jadwal']??'')?>">
<?php crud_field('id_guru','Guru',$edit['id_guru']??'',$teachers);crud_field('id_kelas','Kelas',$edit['id_kelas']??'',$classes);crud_field('id_mapel','Mata pelajaran',$edit['id_mapel']??'',$subjects);crud_field('id_tahun_ajaran','Periode',$edit['id_tahun_ajaran']??'',$years);crud_field('hari','Hari',$edit['hari']??'',array_combine(['Senin','Selasa','Rabu','Kamis','Jumat'],['Senin','Selasa','Rabu','Kamis','Jumat']));crud_field('jam_mulai','Jam mulai',$edit['jam_mulai']??'',null,'time');crud_field('jam_selesai','Jam selesai',$edit['jam_selesai']??'',null,'time');crud_field('ruang','Ruang',$edit['ruang']??'',null,'text',false);?><button class="btn btn-dark">Simpan Penugasan</button></form>
<form method="get" class="card p-3 mb-4 crud-grid"><?php crud_field('q','Cari guru / kelas / mapel / ruang',$search,null,'search',false);foreach(['id_guru'=>['Guru',$teachers],'id_kelas'=>['Kelas',$classes],'id_mapel'=>['Mapel',$subjects],'id_tahun_ajaran'=>['Periode',$years]] as $key=>[$label,$options])crud_field($key,$label,$_GET[$key]??'',$options,'text',false);crud_field('status','Status',$status,['aktif'=>'Aktif','nonaktif'=>'Nonaktif'],'text',false);?><button class="btn btn-dark">Terapkan filter</button></form>
<div class="card p-3"><div class="table-responsive"><table class="table"><thead><tr><th>Guru / Mapel</th><th>Kelas / Periode</th><th>Hari dan jam</th><th>Ruang</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['nama_guru'])?><br><?=e($row['nama_mapel'])?></td><td><?=e($row['nama_kelas'])?><br><?=e($row['tahun_ajaran']?($row['tahun_ajaran'].' '.$row['semester']):'Belum ditetapkan')?></td><td><?=e($row['hari'].' '.$row['jam_mulai'].'–'.$row['jam_selesai'])?></td><td><?=e($row['ruang'])?></td><td><?=e($row['status'])?></td><td><div class="crud-actions"><a class="btn btn-outline-dark" href="?edit=<?=$row['id_jadwal']?>">Edit</a><?php crud_status_actions('id_jadwal',$row['id_jadwal'],$row['status']);?></div></td></tr><?php endforeach;?></tbody></table></div><?php crud_pager($page,$pages,$total);?></div><?php require '../includes/footer.php';
